{
    CTCPerceiveThing perceive; perceive.GiveUpChaseRadius = 40.0f;
    CThing thing; thing.Perceive = &perceive; thing.PBaseDef = &g_creatureDef;
    CAIBrain brain; brain.Creature = &thing;
