        && group.TROLL_STOP_POUNDING_DISTANCE == m2 && group.TROLL_STOP_THROWING_DISTANCE == m3
        && g_aoe.RefCount == 1 && g_trap.RefCount == 1 && g_explosion.RefCount == 1 && g_trapThing.RefCount == 1
